-- 2. MIGRATION  001_license_key_customer_link.sql
-- ══════════════════════════════════════════════════════════════

-- Migration 001: Link license keys to pre-created customers
-- Allows distributor to create customer + branch upfront and issue a key for client onboarding.
-- Backward-compatible: existing standalone keys have customer_id = NULL (old onboard flow still works).

alter table public.license_keys
  add column if not exists customer_id uuid references public.customers(id) on delete cascade;

create index if not exists idx_license_keys_customer on public.license_keys(customer_id);


-- ══════════════════════════════════════════════════════════════
-- 2. MIGRATION  002_screen_announcement_lang.sql
-- ══════════════════════════════════════════════════════════════

-- Add announcement language setting to screens
ALTER TABLE public.screens
  ADD COLUMN IF NOT EXISTS announcement_lang text NOT NULL DEFAULT 'en'
    CHECK (announcement_lang IN ('en', 'ar', 'both'));

-- Update resolve_screen_settings to include announcement_lang in the JSON blob
CREATE OR REPLACE FUNCTION public.resolve_screen_settings(p_screen_id uuid)
RETURNS json
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_screen record;
  v_result json;
BEGIN
  SELECT
    coalesce(s.layout, 'split-standard')       AS layout,
    coalesce(s.theme, 'standard')              AS theme,
    coalesce(s.show_ads, true)                AS show_ads,
    coalesce(s.show_ticker, true)             AS show_ticker,
    s.show_clock,
    s.show_estimated_wait,
    s.numbers_to_show,
    s.orientation,
    coalesce(s.announcement_lang, 'en')        AS announcement_lang
  INTO v_screen
  FROM public.screens s
  WHERE s.id = p_screen_id;

  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  SELECT row_to_json(v_screen) INTO v_result;
  RETURN v_result;
END;
$$;


-- ══════════════════════════════════════════════════════════════
-- 3. MIGRATION  20260630_create_counters_table.sql
-- ══════════════════════════════════════════════════════════════

-- Counter access system
-- Each counter has a unique token; accessing /counter/<token> loads its dashboard.
-- Admin can activate/deactivate or revoke (regenerate token) at any time.

create table if not exists counters (
  id             uuid primary key default gen_random_uuid(),
  customer_id    uuid not null references customers(id) on delete cascade,
  branch_id      uuid not null references branches(id)  on delete cascade,
  name           text not null,
  type           text not null check (type in ('billing', 'kitchen', 'delivery')),
  counter_token  text not null unique default gen_random_uuid()::text,
  is_active      boolean not null default true,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);

create index if not exists counters_branch_id_idx      on counters(branch_id);
create index if not exists counters_customer_id_idx    on counters(customer_id);
create index if not exists counters_counter_token_idx  on counters(counter_token);

-- RLS: service role only (counter actions bypass RLS via service client)
alter table counters enable row level security;

drop policy if exists "service role full access" on counters;
create policy "service role full access"
  on counters for all
  using (true)
  with check (true);


-- ══════════════════════════════════════════════════════════════
-- 4. MIGRATION  20260630_add_kitchen_status.sql
-- ══════════════════════════════════════════════════════════════

-- Add kitchen_status to queue_entries so kitchen counter has its own lifecycle
-- independent of the main queue status field.
--
-- Flow: order desk creates entry (kitchen_status='pending')
--       kitchen marks 'preparing' (optional) then 'ready'
--       billing/delivery counter then calls/delivers the kitchen-ready entry

ALTER TABLE queue_entries
  ADD COLUMN IF NOT EXISTS kitchen_status text NOT NULL DEFAULT 'pending'
  CONSTRAINT queue_entries_kitchen_status_check
    CHECK (kitchen_status IN ('pending', 'preparing', 'ready'));

CREATE INDEX IF NOT EXISTS queue_entries_kitchen_status_idx
  ON queue_entries(branch_id, kitchen_status)
  WHERE status = 'waiting';


-- ══════════════════════════════════════════════════════════════
-- 5. MIGRATION  20260703_counter_presence.sql
-- ══════════════════════════════════════════════════════════════

-- Live presence for counters.
-- Mirrors the last_seen_at heartbeat pattern already used for screens, so
-- staff/admin can tell whether a counter page is actually open right now
-- versus just left active-but-unattended.

ALTER TABLE counters ADD COLUMN IF NOT EXISTS last_seen_at timestamptz;

CREATE INDEX IF NOT EXISTS counters_branch_last_seen_idx
  ON counters(branch_id, last_seen_at);

-- The original counters policy ("service role full access") was declared
-- with `using (true)` and no `TO` clause, so — despite its name — it
-- actually grants every role, including anon, full read/write access to
-- counter_token (the secret that authenticates counter call/recall/deliver
-- actions). Every legitimate read/write already goes through the
-- service-role client in server actions and the DAL, so lock this down.
DROP POLICY IF EXISTS "service role full access" ON counters;

CREATE POLICY "counters_service_role_only"
  ON counters FOR ALL
  TO service_role
  USING (true)
  WITH CHECK (true);

-- Token-free presence lookup: lets a counter page show its sibling
-- counters' online/offline status without ever exposing counter_token or
-- customer_id to the browser. SECURITY DEFINER so it can read past RLS
-- while only ever returning the columns listed below.
CREATE OR REPLACE FUNCTION public.get_branch_counter_presence(p_branch_id uuid)
RETURNS json
LANGUAGE sql
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT coalesce(json_agg(row_to_json(c) ORDER BY c.created_at), '[]'::json)
  FROM (
    SELECT id, name, type, is_active, last_seen_at, created_at
    FROM counters
    WHERE branch_id = p_branch_id
  ) c;
$$;

REVOKE ALL ON FUNCTION public.get_branch_counter_presence(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_branch_counter_presence(uuid) TO anon, authenticated;


-- ══════════════════════════════════════════════════════════════
-- 6. MIGRATION  20260703_add_order_counter.sql
-- ══════════════════════════════════════════════════════════════

-- Adds the 'order' counter type: a token-gated device for taking walk-in
-- orders and issuing queue numbers, unifying order-taking into the same
-- counter model as billing/kitchen/delivery.

ALTER TABLE counters DROP CONSTRAINT IF EXISTS counters_type_check;
ALTER TABLE counters ADD CONSTRAINT counters_type_check
  CHECK (type IN ('order', 'billing', 'kitchen', 'delivery'));


-- ══════════════════════════════════════════════════════════════
-- 7. MIGRATION  20260704_counter_presence_toggle.sql
-- ══════════════════════════════════════════════════════════════

-- Counter online/offline presence indicators are being disabled by default —
-- they need more real-world testing before staff rely on them. Gate the
-- whole feature (heartbeat + presence display) behind a per-branch setting
-- that admins can opt into from Branch Settings.

ALTER TABLE branches ADD COLUMN IF NOT EXISTS counter_presence_enabled boolean NOT NULL DEFAULT false;


-- ══════════════════════════════════════════════════════════════
-- 8. MIGRATION  20260704_user_branches_single.sql
-- ══════════════════════════════════════════════════════════════

-- Formalizes what the UI has always enforced: one staff account (branch_user)
-- is assigned to exactly one branch. The invite form and the reassignment
-- dropdown in /admin/users are both single-select and always replace any
-- prior assignment, so this just makes the database the authority for it too.
-- (ADD CONSTRAINT has no IF NOT EXISTS; guarded so the bundle is re-runnable.)
DO $$ BEGIN
  ALTER TABLE user_branches ADD CONSTRAINT user_branches_one_per_user UNIQUE (user_id);
EXCEPTION WHEN duplicate_table OR duplicate_object THEN NULL; END $$;


-- ══════════════════════════════════════════════════════════════
-- 9. MIGRATION  20260705_counter_accepting_orders.sql
-- ══════════════════════════════════════════════════════════════

-- Lets kitchen staff mark themselves "not accepting orders" for a shift
-- without losing access to their own console — unlike is_active, which also
-- gates the counter token's page access (see getCounterByToken). Only
-- meaningful for kitchen-type counters: the bypass check
-- (hasActiveKitchenCounter) now requires is_active AND accepting_orders.

ALTER TABLE counters ADD COLUMN IF NOT EXISTS accepting_orders boolean NOT NULL DEFAULT true;


-- ══════════════════════════════════════════════════════════════
-- 10. MIGRATION  20260705_kitchen_bypassed_activity_type.sql
-- ══════════════════════════════════════════════════════════════

-- Kitchen going offline mid-service (last active kitchen counter deactivated,
-- deleted, or retyped) silently flips stranded pending/preparing orders to
-- 'ready' so they aren't stuck forever. That's a routing change a manager
-- should be able to see happened, distinct from a normal counter toggle —
-- so it gets its own activity log type instead of reusing an existing one.

ALTER TABLE activity_logs DROP CONSTRAINT IF EXISTS activity_logs_type_check;
ALTER TABLE activity_logs ADD CONSTRAINT activity_logs_type_check
  CHECK (type IN ('joined','called','recalled','completed','cancelled','no-show','reset','paused','resumed','kitchen-bypassed'));


-- ══════════════════════════════════════════════════════════════
-- 11. MIGRATION  20260705_common_bucket_public.sql
-- ══════════════════════════════════════════════════════════════

-- The original migration only flips the flag and assumes the bucket was made
-- by hand in the dashboard. On a fresh project it does not exist yet, so
-- create it here — otherwise every ad upload 404s and the migration is a
-- silent no-op affecting 0 rows.
insert into storage.buckets (id, name, public)
values ('common-bucket', 'common-bucket', true)
on conflict (id) do update set public = true;
-- Ad media (common + branch-specific) is uploaded to the "common-bucket"
-- Storage bucket. It must be public because the public, unauthenticated
-- /display/[token] screens load ad images/videos directly by URL. All
-- uploads/deletes happen server-side via the service-role key (see
-- lib/storage/ads.ts), which bypasses RLS, so no insert/update/delete
-- policies are needed here — only the public-read flag.
--
-- Requires the bucket "common-bucket" to already exist (create it in the
-- Supabase dashboard under Storage first if this affects 0 rows).

UPDATE storage.buckets SET public = true WHERE id = 'common-bucket';


-- ══════════════════════════════════════════════════════════════
-- 12. MIGRATION  20260709_add_call_counter.sql
-- ══════════════════════════════════════════════════════════════

-- Adds the 'call' counter type: a keypad-driven paging station. Staff type
-- any bill number (not necessarily already in the queue) and call it directly
-- to the display. Like the delivery counter, calling registers the bill as an
-- immediately-ready entry (skipping the kitchen stage) so it can be recalled
-- or completed.

ALTER TABLE counters DROP CONSTRAINT IF EXISTS counters_type_check;
ALTER TABLE counters ADD CONSTRAINT counters_type_check
  CHECK (type IN ('order', 'billing', 'kitchen', 'delivery', 'call'));


-- ══════════════════════════════════════════════════════════════
-- 13. SCHOOL QUEUE  20260825_school_queue_system.sql
-- ══════════════════════════════════════════════════════════════

-- ══════════════════════════════════════════════════════════════
-- School Queue Management System
-- ══════════════════════════════════════════════════════════════
-- A second queue product living alongside the existing restaurant/retail
-- flow, in its own tables and its own /school route namespace. Nothing here
-- touches queue_entries / queue_state / counters.
--
-- Why separate tables rather than columns on the existing ones:
--   * tokens are per-department series with letter prefixes (A101, F201…)
--     that reset daily — queue_state is one integer per branch;
--   * a school serves from N windows at once — queue_state.current_serving_number
--     is a single shared slot that concurrent counters would overwrite;
--   * a school token must name the counter to walk to — queue_entries has no
--     counter_id.
--
-- NOTE: deliberately NOT mirrored into supabase/schema.sql. That file opens
-- with a `drop table … cascade` block, so school tables added there would be
-- silently orphaned (or wiped) on every re-run.
-- ══════════════════════════════════════════════════════════════


-- ── Product selector on the tenant ────────────────────────────
-- A customer account is either a business or a school; this drives which
-- product the login lands in.
ALTER TABLE public.customers
  ADD COLUMN IF NOT EXISTS vertical text NOT NULL DEFAULT 'business';

DO $$ BEGIN
  ALTER TABLE public.customers ADD CONSTRAINT customers_vertical_check
    CHECK (vertical IN ('business', 'school'));
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

-- ── Which board a registered screen renders ───────────────────
-- Screens are shared with the existing product (that gives the school the ads
-- cascade, the max_screens_per_branch quota and last_seen_at presence for
-- free). `kind` keeps one screen_token valid at exactly one board route.
ALTER TABLE public.screens
  ADD COLUMN IF NOT EXISTS kind text NOT NULL DEFAULT 'queue';

DO $$ BEGIN
  ALTER TABLE public.screens ADD CONSTRAINT screens_kind_check
    CHECK (kind IN ('queue', 'school'));
EXCEPTION WHEN duplicate_object THEN NULL; END $$;


-- ══════════════════════════════════════════════════════════════
-- 1. SETTINGS (one row per school branch)
-- ══════════════════════════════════════════════════════════════
CREATE TABLE IF NOT EXISTS public.school_settings (
  id                   uuid primary key default gen_random_uuid(),
  customer_id          uuid not null references public.customers(id) on delete cascade,
  branch_id            uuid not null unique references public.branches(id) on delete cascade,
  school_name_en       text not null default '',
  school_name_ar       text not null default '',
  logo_url             text not null default '',
  languages            text[] not null default '{en}',
  ticket_footer_en     text not null default '',
  ticket_footer_ar     text not null default '',
  kiosk_idle_seconds   int  not null default 20 check (kiosk_idle_seconds between 3 and 120),
  priority_enabled     boolean not null default true,
  announce_enabled     boolean not null default true,
  announce_template_en text not null default 'Token {token}, please proceed to {counter}',
  announce_template_ar text not null default 'التذكرة {token}، يرجى التوجه إلى {counter}',
  print_enabled        boolean not null default true,
  -- Locale maps (Region rollout, Phase 2). The _en/_ar columns above are kept
  -- and dual-written until every client is on the maps — see
  -- supabase/migrations/20260904_school_content_locale_jsonb.sql. The `? 'en'`
  -- CHECKs are added by name in the migration-replay section at the end.
  school_name          jsonb not null default '{"en":""}'::jsonb,
  ticket_footer        jsonb not null default '{"en":""}'::jsonb,
  announce_template    jsonb not null default '{"en":"Token {token}, please proceed to {counter}"}'::jsonb,
  -- "Today" must be the school's local day, not UTC. Supabase runs UTC and the
  -- existing product derives dates in JS from toISOString(), which for Qatar
  -- (UTC+3) rolls the day at 03:00 local. Every school date is derived from
  -- these two columns in SQL instead — see school_service_date().
  timezone             text not null default 'Asia/Qatar',
  day_start_time       time not null default '00:00',
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now()
);

CREATE INDEX IF NOT EXISTS school_settings_customer_idx
  ON public.school_settings(customer_id);


-- ══════════════════════════════════════════════════════════════
-- 2. DEPARTMENTS
-- ══════════════════════════════════════════════════════════════
CREATE TABLE IF NOT EXISTS public.school_departments (
  id            uuid primary key default gen_random_uuid(),
  customer_id   uuid not null references public.customers(id) on delete cascade,
  branch_id     uuid not null references public.branches(id) on delete cascade,
  name_en       text not null,
  name_ar       text not null default '',
  -- Locale map (Region rollout, Phase 2) — dual-written alongside name_en/_ar.
  name          jsonb not null default '{"en":""}'::jsonb, -- CHECK name_has_en added in replay section
  prefix        text not null check (prefix ~ '^[A-Z]{1,3}$'),
  number_start  int  not null default 101 check (number_start between 1 and 99999),
  color         text not null default '#0F766E',
  icon          text not null default 'Building2',
  is_priority   boolean not null default false,
  display_order int  not null default 0,
  is_active     boolean not null default true,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

-- Two active departments sharing a prefix would collide on
-- school_tokens(branch_id, service_date, token_code) and start throwing at the
-- kiosk mid-day. Catch it at configuration time instead.
CREATE UNIQUE INDEX IF NOT EXISTS school_departments_branch_prefix_uniq
  ON public.school_departments(branch_id, prefix) WHERE is_active;

CREATE INDEX IF NOT EXISTS school_departments_branch_idx
  ON public.school_departments(branch_id, display_order);


-- ══════════════════════════════════════════════════════════════
-- 3. DAILY CURSOR (one row per department per service day)
-- ══════════════════════════════════════════════════════════════
-- The daily reset falls out of the schema: a new day has no row yet, so the
-- series restarts at the department's number_start. No cron, no reset button.
CREATE TABLE IF NOT EXISTS public.school_department_days (
  id            uuid primary key default gen_random_uuid(),
  customer_id   uuid not null references public.customers(id) on delete cascade,
  branch_id     uuid not null references public.branches(id) on delete cascade,
  department_id uuid not null references public.school_departments(id) on delete cascade,
  service_date  date not null,
  next_number   int  not null,
  created_at    timestamptz not null default now(),
  constraint school_department_days_uniq unique (department_id, service_date)
);


-- ══════════════════════════════════════════════════════════════
-- 4. COUNTERS (service windows)
-- ══════════════════════════════════════════════════════════════
CREATE TABLE IF NOT EXISTS public.school_counters (
  id               uuid primary key default gen_random_uuid(),
  customer_id      uuid not null references public.customers(id) on delete cascade,
  branch_id        uuid not null references public.branches(id) on delete cascade,
  name_en          text not null,
  name_ar          text not null default '',
  -- Locale map (Region rollout, Phase 2) — dual-written alongside name_en/_ar.
  name             jsonb not null default '{"en":""}'::jsonb, -- CHECK name_has_en added in replay section
  counter_token    text not null unique default gen_random_uuid()::text,
  -- Short numeric id a hardware calling keypad identifies itself with.
  keypad_code      text,
  -- Physical key -> action mapping; cheap keypads differ, so this is data.
  keypad_map       jsonb not null default '{}'::jsonb,
  accepts_priority boolean not null default true,
  display_order    int  not null default 0,
  is_active        boolean not null default true,
  is_open          boolean not null default true,
  last_seen_at     timestamptz,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);

CREATE UNIQUE INDEX IF NOT EXISTS school_counters_branch_keypad_uniq
  ON public.school_counters(branch_id, keypad_code) WHERE keypad_code IS NOT NULL;

CREATE INDEX IF NOT EXISTS school_counters_branch_idx
  ON public.school_counters(branch_id, display_order);
CREATE INDEX IF NOT EXISTS school_counters_token_idx
  ON public.school_counters(counter_token);


-- ══════════════════════════════════════════════════════════════
-- 5. COUNTER <-> DEPARTMENT
-- ══════════════════════════════════════════════════════════════
-- A window serves one or more departments. `preference` is the operator's
-- primary-first ordering; it is folded into the call ordering as a small time
-- penalty rather than a hard sort key, so a secondary department can't starve.
CREATE TABLE IF NOT EXISTS public.school_counter_departments (
  id            uuid primary key default gen_random_uuid(),
  customer_id   uuid not null references public.customers(id) on delete cascade,
  counter_id    uuid not null references public.school_counters(id) on delete cascade,
  department_id uuid not null references public.school_departments(id) on delete cascade,
  preference    int  not null default 0,
  created_at    timestamptz not null default now(),
  constraint school_counter_departments_uniq unique (counter_id, department_id)
);

CREATE INDEX IF NOT EXISTS school_counter_departments_dept_idx
  ON public.school_counter_departments(department_id);


-- ══════════════════════════════════════════════════════════════
-- 6. TOKENS
-- ══════════════════════════════════════════════════════════════
CREATE TABLE IF NOT EXISTS public.school_tokens (
  id            uuid primary key default gen_random_uuid(),
  customer_id   uuid not null references public.customers(id) on delete cascade,
  branch_id     uuid not null references public.branches(id) on delete cascade,
  department_id uuid not null references public.school_departments(id) on delete restrict,
  counter_id    uuid references public.school_counters(id) on delete set null,
  service_date  date not null,
  number        int  not null,
  token_code    text not null,
  status        text not null default 'waiting'
                check (status in ('waiting','called','held','served','no-show','cancelled')),
  is_priority   boolean not null default false,
  source        text not null default 'kiosk'
                check (source in ('kiosk','staff','web','api')),
  transferred_from_department_id uuid references public.school_departments(id) on delete set null,
  notes         text not null default '',
  joined_at     timestamptz not null default now(),
  called_at     timestamptz,
  served_at     timestamptz,
  call_count    int not null default 0,
  recall_count  int not null default 0,
  created_at    timestamptz not null default now(),
  constraint school_tokens_code_uniq unique (branch_id, service_date, token_code)
);

-- One live token per window, enforced by the database rather than by a
-- mutable "current_token_id" pointer that would drift on a crashed action.
CREATE UNIQUE INDEX IF NOT EXISTS school_tokens_one_called_per_counter
  ON public.school_tokens(counter_id) WHERE status = 'called';

CREATE INDEX IF NOT EXISTS school_tokens_branch_day_status_idx
  ON public.school_tokens(branch_id, service_date, status);
CREATE INDEX IF NOT EXISTS school_tokens_dept_day_status_idx
  ON public.school_tokens(department_id, service_date, status, joined_at);
CREATE INDEX IF NOT EXISTS school_tokens_customer_idx
  ON public.school_tokens(customer_id);


-- ══════════════════════════════════════════════════════════════
-- 7. ACTIVITY LOG (insert-only)
-- ══════════════════════════════════════════════════════════════
-- activity_logs can't be reused: its `type` CHECK is restaurant-specific and
-- entry_id is an FK to queue_entries.
CREATE TABLE IF NOT EXISTS public.school_activity_logs (
  id            uuid primary key default gen_random_uuid(),
  customer_id   uuid not null references public.customers(id) on delete cascade,
  branch_id     uuid not null references public.branches(id) on delete cascade,
  token_id      uuid references public.school_tokens(id) on delete set null,
  counter_id    uuid references public.school_counters(id) on delete set null,
  department_id uuid references public.school_departments(id) on delete set null,
  performed_by  uuid references public.profiles(id) on delete set null,
  source        text not null default 'staff'
                check (source in ('kiosk','staff','web','api','system')),
  type          text not null
                check (type in ('issued','called','recalled','held','resumed','served',
                                'no-show','cancelled','transferred','counter-opened','counter-closed')),
  token_code    text not null default '',
  message       text not null default '',
  created_at    timestamptz not null default now()
);

CREATE INDEX IF NOT EXISTS school_activity_logs_branch_created_idx
  ON public.school_activity_logs(branch_id, created_at desc);
CREATE INDEX IF NOT EXISTS school_activity_logs_token_idx
  ON public.school_activity_logs(token_id);


-- ══════════════════════════════════════════════════════════════
-- RLS — service role only
-- ══════════════════════════════════════════════════════════════
-- RLS in this schema is self-referentially broken (profiles -> customers), so
-- every read and write goes through the service-role client behind the
-- requireX() guards in lib/dal/session.ts. Same rule as `counters`.
DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY[
    'school_settings', 'school_departments', 'school_department_days',
    'school_counters', 'school_counter_departments', 'school_tokens',
    'school_activity_logs'
  ] LOOP
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', t || '_service_role_only', t);
    EXECUTE format(
      'CREATE POLICY %I ON public.%I FOR ALL TO service_role USING (true) WITH CHECK (true)',
      t || '_service_role_only', t);
  END LOOP;
END $$;


-- ══════════════════════════════════════════════════════════════
-- REALTIME — deliberately NOT via postgres_changes
-- ══════════════════════════════════════════════════════════════
-- The school tables are not added to the supabase_realtime publication, and
-- that is on purpose.
--
-- postgres_changes is delivered to the browser under RLS, so subscribing from
-- a device page would require an anon SELECT policy. The existing product does
-- exactly that (`queue_entries_read_all ... using (true)`), which exposes every
-- tenant's rows to anyone with the publishable key. school_counters is worse
-- still: it holds counter_token, the credential that authorises calling —
-- leaking it is the precise bug migration 20260703_counter_presence.sql had to
-- fix on `counters`.
--
-- So school device surfaces stay on the service-role side of the fence:
--   * instant call/recall updates arrive over a Realtime *broadcast* topic
--     (`school-display-<branch>`), which carries only what the board renders;
--   * state of record is re-read through server actions that use the service
--     client, on a short poll that doubles as the recovery path for a TV whose
--     socket drops with nobody there to reload it.
-- Publishing these tables would add WAL overhead for a subscription nothing
-- can legitimately open.


-- ══════════════════════════════════════════════════════════════
-- FUNCTIONS
-- ══════════════════════════════════════════════════════════════

-- ── school_service_date ───────────────────────────────────────
-- The one place a school "day" is defined. Every token issue, board read,
-- dashboard tile and report must go through this — an RPC and a dashboard that
-- disagree by one day is the support ticket this product would otherwise
-- generate. Never derive the date in JS.
CREATE OR REPLACE FUNCTION public.school_service_date(p_branch_id uuid)
RETURNS date
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT (
    (now() AT TIME ZONE coalesce(s.timezone, 'Asia/Qatar'))
    - coalesce(s.day_start_time, '00:00'::time)::interval
  )::date
  FROM public.branches b
  LEFT JOIN public.school_settings s ON s.branch_id = b.id
  WHERE b.id = p_branch_id;
$$;


-- ── claim_school_token ────────────────────────────────────────
-- Issues the next token in a department's daily series.
--
-- The cursor bump is a single INSERT … ON CONFLICT DO UPDATE on purpose: the
-- one-row upsert holds the row lock until commit, so concurrent kiosks
-- serialize without an advisory lock. A select-then-update would be a TOCTOU
-- race. And because a plpgsql function is one transaction, a failed token
-- insert rolls the increment back — the series stays gapless.
CREATE OR REPLACE FUNCTION public.claim_school_token(
  p_branch_id     uuid,
  p_department_id uuid,
  p_source        text    DEFAULT 'kiosk',
  p_is_priority   boolean DEFAULT false
)
RETURNS public.school_tokens
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_dept   public.school_departments;
  v_date   date;
  v_number int;
  v_token  public.school_tokens;
BEGIN
  SELECT * INTO v_dept
    FROM public.school_departments
   WHERE id = p_department_id AND branch_id = p_branch_id AND is_active;

  IF v_dept.id IS NULL THEN
    RAISE EXCEPTION 'Department % is not an active department of branch %',
      p_department_id, p_branch_id;
  END IF;

  v_date := public.school_service_date(p_branch_id);

  INSERT INTO public.school_department_days
    (customer_id, branch_id, department_id, service_date, next_number)
  VALUES
    (v_dept.customer_id, p_branch_id, p_department_id, v_date, v_dept.number_start + 1)
  ON CONFLICT (department_id, service_date) DO UPDATE
    SET next_number = school_department_days.next_number + 1
  RETURNING next_number - 1 INTO v_number;

  INSERT INTO public.school_tokens
    (customer_id, branch_id, department_id, service_date, number, token_code,
     is_priority, source)
  VALUES
    (v_dept.customer_id, p_branch_id, p_department_id, v_date, v_number,
     v_dept.prefix || v_number::text,
     p_is_priority OR v_dept.is_priority,
     p_source)
  RETURNING * INTO v_token;

  INSERT INTO public.school_activity_logs
    (customer_id, branch_id, token_id, department_id, source, type, token_code, message)
  VALUES
    (v_dept.customer_id, p_branch_id, v_token.id, p_department_id, p_source, 'issued',
     v_token.token_code, v_token.token_code || ' issued — ' || v_dept.name_en);

  RETURN v_token;
END;
$$;


-- ── call_next_school_token ────────────────────────────────────
-- Calls the next token this window should serve, and closes out whatever it
-- was serving.
--
-- Two counters on the same department would otherwise both select the same
-- oldest waiting row, so the pick is FOR UPDATE … SKIP LOCKED: the second
-- caller skips the locked row and takes the next one instead of blocking and
-- then acting on a row it already saw as `waiting`.
--
-- Ordering is a single effective-wait key rather than hard sort columns, so
-- neither the normal lane nor a secondary department can starve:
--   effective_joined_at = joined_at
--                       + preference * p_preference_penalty_minutes
--                       - p_priority_grace_minutes (priority tokens only)
-- A priority visitor jumps the queue, but only past people who have waited
-- less than the grace window.
CREATE OR REPLACE FUNCTION public.call_next_school_token(
  p_counter_id               uuid,
  p_priority_grace_minutes   int DEFAULT 10,
  p_preference_penalty_minutes int DEFAULT 3
)
RETURNS public.school_tokens
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_counter public.school_counters;
  v_date    date;
  v_id      uuid;
  v_token   public.school_tokens;
BEGIN
  SELECT * INTO v_counter
    FROM public.school_counters WHERE id = p_counter_id AND is_active;

  IF v_counter.id IS NULL THEN
    RAISE EXCEPTION 'Counter % not found or inactive', p_counter_id;
  END IF;

  v_date := public.school_service_date(v_counter.branch_id);

  SELECT t.id INTO v_id
    FROM public.school_tokens t
    JOIN public.school_counter_departments cd
      ON cd.department_id = t.department_id
     AND cd.counter_id = p_counter_id
   WHERE t.branch_id = v_counter.branch_id
     AND t.service_date = v_date
     AND t.status = 'waiting'
     AND (v_counter.accepts_priority OR NOT t.is_priority)
   ORDER BY
     t.joined_at
       + make_interval(mins => cd.preference * p_preference_penalty_minutes)
       - CASE WHEN t.is_priority
              THEN make_interval(mins => p_priority_grace_minutes)
              ELSE interval '0' END
   LIMIT 1
   FOR UPDATE OF t SKIP LOCKED;

  IF v_id IS NULL THEN
    RETURN NULL;
  END IF;

  -- Close out the previous token first: the partial unique index allows only
  -- one 'called' row per counter.
  UPDATE public.school_tokens
     SET status = 'served', served_at = now()
   WHERE counter_id = p_counter_id AND status = 'called';

  UPDATE public.school_tokens
     SET status     = 'called',
         counter_id = p_counter_id,
         called_at  = now(),
         call_count = call_count + 1
   WHERE id = v_id
  RETURNING * INTO v_token;

  INSERT INTO public.school_activity_logs
    (customer_id, branch_id, token_id, counter_id, department_id,
     source, type, token_code, message)
  VALUES
    (v_token.customer_id, v_token.branch_id, v_token.id, p_counter_id,
     v_token.department_id, 'staff', 'called', v_token.token_code,
     v_token.token_code || ' called to ' || v_counter.name_en);

  RETURN v_token;
END;
$$;


-- ── get_school_board ──────────────────────────────────────────
-- Everything one TV needs, in one round trip.
--
-- The board is ONE ROW PER OPEN WINDOW, always visible, showing that window's
-- current token or nothing — not "the last N tokens called", which would make
-- a quiet counter vanish from the board a few calls later.
CREATE OR REPLACE FUNCTION public.get_school_board(p_screen_token text)
RETURNS json
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_screen   public.screens;
  v_branch   public.branches;
  v_customer public.customers;
  v_settings public.school_settings;
  v_date     date;
  v_counters json;
  v_recent   json;
  v_depts    json;
  v_ads      json;
  v_tickers  json;
BEGIN
  SELECT * INTO v_screen
    FROM public.screens WHERE screen_token = p_screen_token AND is_active;

  IF v_screen.id IS NULL THEN
    RETURN json_build_object('status', 'not-found');
  END IF;

  -- Presence is deliberately NOT written here. This read is served from an
  -- in-process cache (lib/cache/store.ts) and usually never reaches Postgres,
  -- so it can no longer double as a heartbeat. The app writes screens.last_seen_at
  -- separately and throttled — lib/cache/presence.ts#touchScreen. That is also
  -- why the function is STABLE: it has no side effects.

  SELECT * INTO v_branch   FROM public.branches  WHERE id = v_screen.branch_id;
  SELECT * INTO v_customer FROM public.customers WHERE id = v_screen.customer_id;

  IF NOT v_customer.is_active
     OR (v_customer.plan_expires_at IS NOT NULL AND v_customer.plan_expires_at < now()) THEN
    RETURN json_build_object('status', 'expired');
  END IF;

  SELECT * INTO v_settings FROM public.school_settings WHERE branch_id = v_branch.id;
  v_date := public.school_service_date(v_branch.id);

  -- One row per window, with whatever it is currently calling.
  SELECT coalesce(json_agg(row_to_json(r) ORDER BY r.display_order, r.name_en), '[]'::json)
    INTO v_counters
    FROM (
      SELECT c.id, c.name_en, c.name_ar, c.display_order, c.is_open, c.last_seen_at,
             t.id            AS token_id,
             t.token_code,
             t.called_at,
             t.recall_count,
             t.is_priority,
             d.name_en       AS department_en,
             d.name_ar       AS department_ar,
             d.color         AS department_color
        FROM public.school_counters c
        LEFT JOIN public.school_tokens t
               ON t.counter_id = c.id
              AND t.status = 'called'
              AND t.service_date = v_date
        LEFT JOIN public.school_departments d ON d.id = t.department_id
       WHERE c.branch_id = v_branch.id AND c.is_active
    ) r;

  SELECT coalesce(json_agg(row_to_json(r) ORDER BY r.served_at DESC), '[]'::json)
    INTO v_recent
    FROM (
      SELECT t.token_code, t.served_at, c.name_en AS counter_en, c.name_ar AS counter_ar
        FROM public.school_tokens t
        LEFT JOIN public.school_counters c ON c.id = t.counter_id
       WHERE t.branch_id = v_branch.id
         AND t.service_date = v_date
         AND t.status = 'served'
       ORDER BY t.served_at DESC
       LIMIT 8
    ) r;

  SELECT coalesce(json_agg(row_to_json(r) ORDER BY r.display_order), '[]'::json)
    INTO v_depts
    FROM (
      SELECT d.id, d.name_en, d.name_ar, d.color, d.display_order,
             count(t.id) FILTER (WHERE t.status = 'waiting') AS waiting
        FROM public.school_departments d
        LEFT JOIN public.school_tokens t
               ON t.department_id = d.id AND t.service_date = v_date
       WHERE d.branch_id = v_branch.id AND d.is_active
       GROUP BY d.id
    ) r;

  -- Ads: screen override wins, else branch + customer merged per branch_ad_mode.
  -- Same cascade as get_screen_data — kept in sync deliberately.
  -- Projected to the six fields the clients read (web SchoolBoard, Flutter
  -- BoardAd) rather than json_agg'ing whole rows: this packet is re-served on
  -- every poll and SSE frame, so file_size_bytes and timestamps are pure weight.
  DECLARE
    v_screen_ad_count int;
  BEGIN
    SELECT count(*) INTO v_screen_ad_count
      FROM public.screen_ads sa WHERE sa.screen_id = v_screen.id;

    IF v_screen_ad_count > 0 THEN
      SELECT json_agg(json_build_object(
                 'id', a.id, 'file_url', a.file_url, 'file_type', a.file_type,
                 'duration_seconds', a.duration_seconds, 'is_active', a.is_active,
                 'audio_enabled', a.audio_enabled) ORDER BY sa.display_order ASC) INTO v_ads
        FROM public.screen_ads sa
        JOIN public.ads a ON a.id = sa.ad_id
       WHERE sa.screen_id = v_screen.id AND a.is_active = true;
    ELSE
      DECLARE
        v_branch_ads   json;
        v_customer_ads json;
      BEGIN
        SELECT json_agg(json_build_object(
                 'id', a.id, 'file_url', a.file_url, 'file_type', a.file_type,
                 'duration_seconds', a.duration_seconds, 'is_active', a.is_active,
                 'audio_enabled', a.audio_enabled) ORDER BY a.display_order) INTO v_branch_ads
          FROM public.ads a WHERE a.branch_id = v_branch.id AND a.is_active = true;

        SELECT json_agg(json_build_object(
                 'id', a.id, 'file_url', a.file_url, 'file_type', a.file_type,
                 'duration_seconds', a.duration_seconds, 'is_active', a.is_active,
                 'audio_enabled', a.audio_enabled) ORDER BY a.display_order) INTO v_customer_ads
          FROM public.ads a
         WHERE a.customer_id = v_customer.id AND a.branch_id IS NULL AND a.is_active = true;

        IF v_branch_ads IS NULL THEN
          v_ads := v_customer_ads;
        ELSIF v_customer_ads IS NULL THEN
          v_ads := v_branch_ads;
        ELSE
          CASE v_customer.branch_ad_mode
            WHEN 'replace' THEN v_ads := v_branch_ads;
            WHEN 'prepend' THEN v_ads := (SELECT json_agg(x) FROM (SELECT * FROM json_array_elements(v_branch_ads) UNION ALL SELECT * FROM json_array_elements(v_customer_ads)) x);
            ELSE                v_ads := (SELECT json_agg(x) FROM (SELECT * FROM json_array_elements(v_customer_ads) UNION ALL SELECT * FROM json_array_elements(v_branch_ads)) x);
          END CASE;
        END IF;
      END;
    END IF;
  END;

  SELECT json_agg(json_build_object('id', t.id, 'message', t.message) ORDER BY t.display_order) INTO v_tickers
    FROM public.ticker_messages t
   WHERE t.is_active = true
     AND (t.branch_id = v_branch.id OR (t.branch_id IS NULL AND t.customer_id = v_customer.id));

  RETURN json_build_object(
    'status',      'ok',
    'screenId',    v_screen.id,
    'branchId',    v_branch.id,
    'customerId',  v_customer.id,
    'serviceDate', v_date,
    'schoolName',  coalesce(nullif(v_settings.school_name_en, ''), v_customer.business_name),
    'schoolNameAr', coalesce(v_settings.school_name_ar, ''),
    'logoUrl',     coalesce(nullif(v_settings.logo_url, ''), v_customer.logo_url),
    'primaryColor', v_customer.primary_color,
    'announcementLang', v_screen.announcement_lang,
    'announceEnabled',  coalesce(v_settings.announce_enabled, true),
    'announceTemplateEn', coalesce(v_settings.announce_template_en, 'Token {token}, please proceed to {counter}'),
    'announceTemplateAr', coalesce(v_settings.announce_template_ar, ''),
    'showClock',   v_screen.show_clock,
    'tickerText',  v_branch.ticker_text,
    'counters',    v_counters,
    'recent',      v_recent,
    'departments', v_depts,
    'ads',         coalesce(v_ads, '[]'::json),
    'tickers',     coalesce(v_tickers, '[]'::json)
  );
END;
$$;


-- The school RPCs are only ever called from server actions and the DAL, both
-- of which use the service-role client. Nothing here is reachable from a
-- browser session.
REVOKE ALL ON FUNCTION public.school_service_date(uuid) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.claim_school_token(uuid, uuid, text, boolean) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.call_next_school_token(uuid, int, int) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.get_school_board(text) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION public.school_service_date(uuid) TO service_role;
GRANT EXECUTE ON FUNCTION public.claim_school_token(uuid, uuid, text, boolean) TO service_role;
GRANT EXECUTE ON FUNCTION public.call_next_school_token(uuid, int, int) TO service_role;
GRANT EXECUTE ON FUNCTION public.get_school_board(text) TO service_role;


-- ══════════════════════════════════════════════════════════════
-- 14. MIGRATION  20260826_license_key_vertical.sql
-- ══════════════════════════════════════════════════════════════

-- Which product a license key entitles its customer to.
--
-- Until now `customers.vertical` was read in four places but written in none:
-- onboarding always produced the column default ('business'), so the only way
-- to create a school tenant was a manual UPDATE. The choice belongs at the
-- point of sale instead — the distributor picks the system when issuing the
-- key, and onboardAction copies it onto the customer it creates.
--
-- 'business' is the hotel/restaurant queue product. The stored value is kept
-- as-is (it is the column default on customers and is already constrained
-- there); the distributor UI labels it "Hotel Queue System".

ALTER TABLE public.license_keys
  ADD COLUMN IF NOT EXISTS vertical text NOT NULL DEFAULT 'business';

DO $$ BEGIN
  ALTER TABLE public.license_keys ADD CONSTRAINT license_keys_vertical_check
    CHECK (vertical IN ('business', 'school'));
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

-- Keys the distributor pre-linked to a customer must agree with that customer,
-- otherwise redeeming one would silently re-vertical a tenant that already has
-- rows in the other product's tables.
UPDATE public.license_keys lk
   SET vertical = c.vertical
  FROM public.customers c
 WHERE lk.customer_id = c.id
   AND lk.vertical IS DISTINCT FROM c.vertical;

CREATE INDEX IF NOT EXISTS license_keys_vertical_idx
  ON public.license_keys(vertical);


-- ══════════════════════════════════════════════════════════════
-- 15. MIGRATION  20260828_ad_audio.sql
-- ══════════════════════════════════════════════════════════════

-- Per-ad audio opt-in for display screens.
--
-- Video ads on the school TV board (and the business board) have always been
-- forced `muted` in the player, because a wall of auto-playing video with
-- overlapping soundtracks is unusable. The school display now shows one ad at a
-- time, so a single ad's audio is safe — but only when the manager asked for
-- it. This flag is that opt-in; the player unmutes a video only when the ad has
-- `audio_enabled` AND the board's audio has been unlocked.
--
-- Images ignore the flag. Existing ads default to silent, matching today's
-- behaviour.

ALTER TABLE public.ads
  ADD COLUMN IF NOT EXISTS audio_enabled boolean NOT NULL DEFAULT false;

-- get_school_board / get_screen_data both json_agg() the whole ads row, so the
-- new column reaches the client with no RPC change.


-- ══════════════════════════════════════════════════════════════
-- 16. MIGRATION  20260901_school_entitlements.sql
-- ══════════════════════════════════════════════════════════════

-- ══════════════════════════════════════════════════════════════
-- School entitlements: departments & counters are sold, not free
-- ══════════════════════════════════════════════════════════════
-- Until now a school tenant could add unlimited departments and counters from
-- /school/departments and /school/counters. Both are billable capacity (each
-- counter is a staffed window with its own console link; each department is a
-- token series on the kiosk and the TV), so the ceiling moves to the
-- distributor: they assign the numbers, the tenant spends them.
--
-- Per BRANCH, not per customer — matching plans.max_screens_per_branch. A
-- multi-campus tenant gets the same allowance at each campus rather than a
-- shared pool that one campus could drain.
--
-- Quotas count ACTIVE rows only. Departments and counters are never hard
-- deleted (school_tokens references them), so deactivating is how a tenant
-- frees a slot to spend elsewhere.
-- ══════════════════════════════════════════════════════════════

ALTER TABLE public.customers
  ADD COLUMN IF NOT EXISTS max_school_departments int NOT NULL DEFAULT 1,
  ADD COLUMN IF NOT EXISTS max_school_counters    int NOT NULL DEFAULT 1;

DO $$ BEGIN
  ALTER TABLE public.customers ADD CONSTRAINT customers_max_school_departments_check
    CHECK (max_school_departments BETWEEN 0 AND 200);
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
  ALTER TABLE public.customers ADD CONSTRAINT customers_max_school_counters_check
    CHECK (max_school_counters BETWEEN 0 AND 200);
EXCEPTION WHEN duplicate_object THEN NULL; END $$;


-- ── Backfill: nobody loses what they already run ──────────────
-- The default of 1 would put every existing school instantly over quota (the
-- onboarding flow seeds 8 departments). Grant each tenant its current
-- high-water mark across its branches; the distributor can lower it later.
UPDATE public.customers c
SET max_school_departments = GREATEST(c.max_school_departments, u.peak)
FROM (
  SELECT customer_id, MAX(per_branch) AS peak
  FROM (
    SELECT customer_id, branch_id, count(*) AS per_branch
    FROM public.school_departments
    WHERE is_active
    GROUP BY customer_id, branch_id
  ) b
  GROUP BY customer_id
) u
WHERE u.customer_id = c.id;

UPDATE public.customers c
SET max_school_counters = GREATEST(c.max_school_counters, u.peak)
FROM (
  SELECT customer_id, MAX(per_branch) AS peak
  FROM (
    SELECT customer_id, branch_id, count(*) AS per_branch
    FROM public.school_counters
    WHERE is_active
    GROUP BY customer_id, branch_id
  ) b
  GROUP BY customer_id
) u
WHERE u.customer_id = c.id;


-- ══════════════════════════════════════════════════════════════
-- 17. MIGRATION  20260901_device_pairing_codes.sql
-- ══════════════════════════════════════════════════════════════

-- ══════════════════════════════════════════════════════════════
-- Device pairing codes  (short-lived 6-digit provisioning)
-- ══════════════════════════════════════════════════════════════
-- The kiosk tablet and the waiting-area TV are provisioned with an opaque
-- 48-char credential (branches.branch_token / screens.screen_token). Those
-- stay — they sit in the API path and are the only thing standing between a
-- stranger and a tenant's queue, so they must not shrink.
--
-- What shrinks is the thing a human types. The dashboard mints a 6-digit code
-- that maps to one branch (kiosk) or one screen (display) for a few minutes;
-- the device posts it once to /api/pair and gets the real long token back,
-- which it then stores locally and uses forever after. Standard smart-TV
-- pairing. A keyboard-less, camera-less TV never has to see the long string.
--
-- NOT mirrored into supabase/schema.sql — same reason as the school tables:
-- that file's opening `drop table … cascade` block would orphan it.
-- ══════════════════════════════════════════════════════════════

CREATE TABLE IF NOT EXISTS public.device_pairing_codes (
  id           uuid        primary key default gen_random_uuid(),
  code         text        not null check (code ~ '^[0-9]{6}$'),
  customer_id  uuid        not null references public.customers(id) on delete cascade,
  branch_id    uuid        not null references public.branches(id) on delete cascade,
  role         text        not null check (role in ('kiosk','display')),
  -- Set for role='display' (which screen), null for role='kiosk'.
  screen_id    uuid        references public.screens(id) on delete cascade,
  created_by   uuid        references public.profiles(id) on delete set null,
  created_at   timestamptz not null default now(),
  expires_at   timestamptz not null,
  consumed_at  timestamptz,
  consumed_ip  text
);

-- A code string is unique only while it is still claimable. Once consumed (or
-- swept after expiry) the same six digits can be handed out again. The route
-- deletes expired rows before minting, so this stays small.
CREATE UNIQUE INDEX IF NOT EXISTS device_pairing_codes_live_code_idx
  ON public.device_pairing_codes (code)
  WHERE consumed_at IS NULL;

CREATE INDEX IF NOT EXISTS device_pairing_codes_target_idx
  ON public.device_pairing_codes (branch_id, role);

CREATE INDEX IF NOT EXISTS device_pairing_codes_expires_idx
  ON public.device_pairing_codes (expires_at);

-- RLS: service-role only, matching the school tables and `counters`. Every
-- read/write goes through the service client behind the requireX() guards
-- (dashboard) or the rate-limited /api/pair route (device).
ALTER TABLE public.device_pairing_codes ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS device_pairing_codes_service_role_only ON public.device_pairing_codes;
CREATE POLICY device_pairing_codes_service_role_only
  ON public.device_pairing_codes FOR ALL TO service_role
  USING (true) WITH CHECK (true);


-- ══════════════════════════════════════════════════════════════
-- 18. MIGRATION  20260902_school_public_tracking.sql
-- ══════════════════════════════════════════════════════════════

-- ══════════════════════════════════════════════════════════════
-- Public ticket tracking: QR on the printed ticket → live waiting page
-- ══════════════════════════════════════════════════════════════
-- The number printed on a ticket is only ever true at the instant it's
-- issued. This gives every school_tokens row a short, non-enumerable public
-- code and one RPC that answers "where do I stand right now" for it — the
-- server the printed QR points at.
--
-- Billable add-on, gated the same way school entitlements are
-- (20260901_school_entitlements.sql): a plain column on customers, set only
-- by the distributor. A second column on school_settings lets the school
-- itself turn its own grant off (e.g. no data plan expected in the lobby).
-- Effective = both true.
--
-- NOT mirrored into supabase/schema.sql — its opening `drop table … cascade`
-- would orphan this.
-- ══════════════════════════════════════════════════════════════


-- ── 1. Public code generator ────────────────────────────────────
-- 8 chars from a 30-symbol alphabet (~39 bits — not guessable by scanning
-- sequential codes) with the characters that get misread aloud at a counter
-- or mistyped by hand removed: 0/O, 1/I/L, U/V confusable pairs collapsed to
-- one. Drawn from gen_random_bytes, not random(): this is a capability
-- handle, not a display id.
--
-- search_path pins `extensions` alongside `public` because this runs as a
-- column DEFAULT from inside claim_school_token(), which is
-- `SET search_path = public` — without `extensions` on the path, pgcrypto's
-- gen_random_bytes() is invisible there and every token INSERT fails with
-- "function gen_random_bytes(integer) does not exist".
CREATE OR REPLACE FUNCTION public.gen_school_public_code() RETURNS text
LANGUAGE plpgsql
SET search_path = public, extensions
AS $$
DECLARE
  alphabet text := '23456789ABCDEFGHJKMNPQRSTVWXYZ';
  len      int  := length(alphabet);
  code     text;
  i        int;
BEGIN
  LOOP
    code := '';
    FOR i IN 1..8 LOOP
      code := code || substr(alphabet, (get_byte(gen_random_bytes(1), 0) % len) + 1, 1);
    END LOOP;
    -- Collision odds at 8 chars/30 symbols are astronomically low; the retry
    -- loop exists so this is safe by construction rather than by odds.
    EXIT WHEN NOT EXISTS (SELECT 1 FROM public.school_tokens WHERE public_code = code);
  END LOOP;
  RETURN code;
END;
$$;


-- ── 2. Column on school_tokens ──────────────────────────────────
ALTER TABLE public.school_tokens ADD COLUMN IF NOT EXISTS public_code text;

-- Unique index BEFORE the backfill: the generator's own collision check is a
-- seq scan without it, which turns backfilling an existing token table into
-- an O(n^2) migration.
CREATE UNIQUE INDEX IF NOT EXISTS school_tokens_public_code_uniq
  ON public.school_tokens(public_code);

UPDATE public.school_tokens
   SET public_code = public.gen_school_public_code()
 WHERE public_code IS NULL;

-- A column default (not an edit to claim_school_token) so every issuance
-- path — the kiosk RPC, staff walk-in, anything added later — gets a code
-- for free, with no way to forget one.
ALTER TABLE public.school_tokens ALTER COLUMN public_code SET DEFAULT public.gen_school_public_code();
ALTER TABLE public.school_tokens ALTER COLUMN public_code SET NOT NULL;


-- ── 3. The two gate columns ─────────────────────────────────────
-- Distributor grant defaults false — it's a sale, nobody gets it by
-- accident. School's own switch defaults true — once bought, it should just
-- work without an extra step.
ALTER TABLE public.customers
  ADD COLUMN IF NOT EXISTS school_public_tracking_enabled boolean NOT NULL DEFAULT false;

ALTER TABLE public.school_settings
  ADD COLUMN IF NOT EXISTS public_tracking_enabled boolean NOT NULL DEFAULT true;


-- ── 4. get_public_ticket_status ─────────────────────────────────
-- One round trip for the public page: gate check, ticket identity, live
-- position, now-serving, and an ETA range. SECURITY DEFINER + revoked from
-- PUBLIC like every other school RPC — reached only through
-- app/api/public/ticket/[code]/route.ts on the service-role client, never
-- directly with the anon/publishable key. That keeps this feature's traffic
-- funnelled through our own caching and error handling, exactly like every
-- other device surface in this schema.
CREATE OR REPLACE FUNCTION public.get_public_ticket_status(p_code text)
RETURNS json
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_token          public.school_tokens;
  v_dept           public.school_departments;
  v_branch         public.branches;
  v_customer       public.customers;
  v_settings       public.school_settings;
  v_counter        public.school_counters;
  v_today          date;
  v_is_today       boolean;
  v_enabled        boolean;
  v_waiting_ahead  int;
  v_now_serving    text;
  v_pace_count     int;
  v_pace_min       timestamptz;
  v_pace_max       timestamptz;
  v_avg_gap_secs   numeric;
  v_eta_secs       numeric;
BEGIN
  SELECT * INTO v_token FROM public.school_tokens WHERE public_code = p_code;
  IF v_token.id IS NULL THEN
    RETURN json_build_object('status', 'not-found');
  END IF;

  SELECT * INTO v_customer FROM public.customers WHERE id = v_token.customer_id;
  SELECT * INTO v_branch   FROM public.branches  WHERE id = v_token.branch_id;
  SELECT * INTO v_settings FROM public.school_settings WHERE branch_id = v_token.branch_id;
  SELECT * INTO v_dept     FROM public.school_departments WHERE id = v_token.department_id;

  IF NOT v_customer.is_active
     OR (v_customer.plan_expires_at IS NOT NULL AND v_customer.plan_expires_at < now()) THEN
    RETURN json_build_object('status', 'expired');
  END IF;

  -- Effective gate: distributor grant AND the school's own switch. A branch
  -- with no settings row yet still defaults to on, matching the column
  -- default — nothing to configure before this works.
  v_enabled := coalesce(v_customer.school_public_tracking_enabled, false)
           AND coalesce(v_settings.public_tracking_enabled, true);

  IF NOT v_enabled THEN
    RETURN json_build_object('status', 'disabled');
  END IF;

  v_today    := public.school_service_date(v_token.branch_id);
  v_is_today := (v_token.service_date = v_today);

  -- Same predicate as countWaitingAhead() in lib/actions/school-tokens.ts —
  -- must never disagree with the number printed on the ticket.
  SELECT count(*) INTO v_waiting_ahead
    FROM public.school_tokens
   WHERE branch_id = v_token.branch_id
     AND department_id = v_token.department_id
     AND service_date = v_token.service_date
     AND status IN ('waiting', 'held')
     AND joined_at < v_token.joined_at;

  IF v_token.counter_id IS NOT NULL AND v_token.status = 'called' THEN
    SELECT * INTO v_counter FROM public.school_counters WHERE id = v_token.counter_id;
  END IF;

  -- What the department is calling right now, regardless of which counter.
  SELECT token_code INTO v_now_serving
    FROM public.school_tokens
   WHERE department_id = v_token.department_id
     AND service_date = v_token.service_date
     AND status = 'called'
   ORDER BY called_at DESC
   LIMIT 1;

  -- Pace: average gap between the last 10 calls in this department today.
  -- Throughput, not a per-visit service-time guess — what a visitor actually
  -- experiences across however many counters happen to be open.
  SELECT count(*), min(called_at), max(called_at)
    INTO v_pace_count, v_pace_min, v_pace_max
    FROM (
      SELECT called_at FROM public.school_tokens
       WHERE department_id = v_token.department_id
         AND service_date = v_token.service_date
         AND called_at IS NOT NULL
       ORDER BY called_at DESC
       LIMIT 10
    ) recent;

  IF v_pace_count >= 3 AND v_pace_max > v_pace_min THEN
    v_avg_gap_secs := extract(epoch FROM (v_pace_max - v_pace_min)) / (v_pace_count - 1);
  ELSE
    -- Not enough samples yet today — fall back to the branch's configured
    -- average service time rather than showing nothing.
    v_avg_gap_secs := coalesce(v_branch.avg_service_time, 5) * 60;
  END IF;

  v_eta_secs := v_waiting_ahead * v_avg_gap_secs;

  RETURN json_build_object(
    'status',            'ok',
    'schoolNameEn',      coalesce(nullif(v_settings.school_name_en, ''), v_customer.business_name),
    'schoolNameAr',      coalesce(v_settings.school_name_ar, ''),
    'logoUrl',           coalesce(nullif(v_settings.logo_url, ''), v_customer.logo_url),
    'languages',         coalesce(v_settings.languages, ARRAY['en']),
    'tokenCode',         v_token.token_code,
    'tokenStatus',       v_token.status,
    'isPriority',        v_token.is_priority,
    'joinedAt',          v_token.joined_at,
    'calledAt',          v_token.called_at,
    'departmentNameEn',  v_dept.name_en,
    'departmentNameAr',  v_dept.name_ar,
    'counterNameEn',     v_counter.name_en,
    'counterNameAr',     v_counter.name_ar,
    'serviceDate',       v_token.service_date,
    'isToday',           v_is_today,
    'waitingAhead',      v_waiting_ahead,
    'nowServingCode',    v_now_serving,
    'etaSeconds',        round(v_eta_secs),
    'paceSampleCount',   v_pace_count
  );
END;
$$;

REVOKE ALL ON FUNCTION public.get_public_ticket_status(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_public_ticket_status(text) TO service_role;


